#!/usr/bin/env bash
# Task 6: compile the whole project, run Main, then compare the output.
# Do not edit this file.
set -u
cd "$(dirname "$0")/.." || exit 1

echo "=== Task 6: Main ==="
rm -rf out
mkdir out
javac -encoding UTF-8 -d out tests/Check.java || exit 1

if ! java -cp out Check --started '\bmain\b' src/Main.java; then
    echo "Nothing written yet in: src/Main.java"
    echo
    echo "NOT STARTED"
    exit 1
fi

if ! ERRORS=$(javac -encoding UTF-8 -d out src/*.java 2>&1); then
    echo "[ ] compiles"
    echo "$ERRORS" | grep -m1 'error:' | sed 's/^/    /'
    echo
    echo "INCOMPLETE (does not compile)"
    exit 1
fi
echo "[x] compiles"

java -cp out Main > out/output.txt 2>&1
java -cp out Check --compare out/output.txt \
    "Java Basics by Suda (2024)" \
    "P001 Notebook - 59.5 THB (stock: 20)" \
    "Shop: Campus Store (3 products)" \
    "Total stock value: 2440.0 THB"
